import { defineComponent, type Definition } from "../../lib/define.ts";
import { css } from "../../lib/css.ts";
import { AI_ICON_MASK } from "../../lib/helpers.ts";
import { SENTINEL } from "../../lib/sentinel.ts";
import { appendGenerated } from "../../lib/aliases.ts";
import { button as buttonRaw } from "../../generated/component-styles.ts";

/**
 * The shared `AI_ICON_MASK` value requires runtime interpolation, so its rule is appended to the
 * `.css`-authored record (`button.css`) via {@link appendGenerated}.
 */
const interpolatedRules = (p: string) => // prettier-ignore
css`
/* The ai glyph, added automatically to every AI button and painted in its own colour. */
.${p}button.-color-ai::before,
.${p}button.-color-ai-secondary::before {
  content: "";
  inline-size: 1em;
  block-size: 1em;
  flex: none;
  -webkit-mask: ${AI_ICON_MASK};
  mask: ${AI_ICON_MASK};
}

/* An explicit glyph class takes precedence over the default AI glyph while keeping the AI palette. */
.${p}button.-color-ai:is([class^="-icon-"], [class*=" -icon-"])::before,
.${p}button.-color-ai-secondary:is([class^="-icon-"], [class*=" -icon-"])::before {
  -webkit-mask: var(--pantoken-glyph) center / contain no-repeat;
  mask: var(--pantoken-glyph) center / contain no-repeat;
}
`;

/** The `button` component record: an accessible action control styled from the token palette, primary by default. */
export const button: Definition = defineComponent({
  name: "button",
  css: (p) => appendGenerated(buttonRaw.replaceAll(SENTINEL, p), interpolatedRules(p)),
});

/** Standalone `button` stylesheet — the prefixed CSS for the action button, ready to ship as a `.css` file. */
export const buttonCss: Definition["css"] = button.css;

/**
 * The spacing utilities — margin/padding classes on the pantoken spacing scale, with logical sides,
 * each in a short spelling (`-mb-sm`) and a fully long, word-spelled one (`-margin-bottom-small`).
 *
 * Each rule matches via `globalModifierSelector` (`@pantoken/utils`) — the modifier class repeated 3x
 * for a deterministic specificity win, applying to any registered component (core or plugin-authored)
 * or standalone, with a single fixed-size selector per rule, no per-component fan-out. This replaced an
 * earlier bare-only fallback that avoided a real ~3s/940KB generation-time regression from enumerating
 * ~70 components per rule under the old mechanism.
 *
 * @module
 */
import { defineUtility, type Definition } from "../../lib/define.ts";
import { css } from "../../lib/css.ts";
import {
  SPACING_AUTO_STEP,
  SPACING_PROPERTIES,
  SPACING_SIDES,
  SPACING_STEPS,
  type SpacingProperty,
  type SpacingStep,
} from "../../lib/helpers.ts";
import { globalModifierSelector } from "@pantoken/utils";

/** The steps a boxed property takes — margin also gets `auto`. */
const stepsFor = (property: SpacingProperty): readonly SpacingStep[] =>
  property.css === "margin" ? [...SPACING_STEPS, SPACING_AUTO_STEP] : SPACING_STEPS;

/**
 * `[key, value]` pairs for the short/legacy loop below: one per step's short key, plus a `none` twin
 * for the zero step (both `-m-0` and `-m-none` have shipped since before the long spelling existed).
 */
const legacyStepEntries = (steps: readonly SpacingStep[]): Array<readonly [string, string]> =>
  steps.flatMap((step) =>
    step.short === "0"
      ? ([
          [step.short, step.value],
          [step.long, step.value],
        ] as const)
      : ([[step.short, step.value]] as const),
  );

/**
 * Short spellings (`-m-sm`) and the legacy long-property-word twin (`-margin-sm`) — concatenated
 * side, short step. Unchanged shape from before the long spelling existed.
 */
function shortAndLegacyRules(p: string): string[] {
  const rules: string[] = [];
  for (const property of SPACING_PROPERTIES) {
    const stepEntries = legacyStepEntries(stepsFor(property));
    for (const letter of [property.short, property.long]) {
      for (const side of SPACING_SIDES) {
        for (const [step, value] of stepEntries) {
          const name = `${letter}${side.short}-${step}`;
          rules.push(
            `${globalModifierSelector(p, name)} { ${property.css}${side.suffix}: ${value}; }`,
          );
        }
      }
    }
  }
  return rules;
}

/**
 * Fully long, dash-separated spellings — property word, side word, and step word all spelled out
 * (`-margin-bottom-small`). A handful of these collide with a "no side" legacy long selector above
 * (e.g. `-margin-none`, `-margin-auto`) — harmless duplicate rules, not worth special-casing.
 */
function fullyLongRules(p: string): string[] {
  const rules: string[] = [];
  for (const property of SPACING_PROPERTIES) {
    for (const side of SPACING_SIDES) {
      for (const step of stepsFor(property)) {
        const sidePart = side.long ? `${side.long}-` : "";
        const name = `${property.long}-${sidePart}${step.long}`;
        rules.push(
          `${globalModifierSelector(p, name)} { ${property.css}${side.suffix}: ${step.value}; }`,
        );
      }
    }
  }
  return rules;
}

/** The spacing utility — margin and padding classes on the spacing scale, with logical sides. */
export const spacing: Definition = defineUtility({
  name: "spacing",
  css: (p) => {
    const rules = [...shortAndLegacyRules(p), ...fullyLongRules(p)];

    // prettier-ignore
    return css`/**
 * @utility spacing
 * @selector .--p-md
 * @global
 * @summary Margin and padding utilities — \`.--m<side>-<step>\` / \`.--margin-<side>-<step>\` and \`.--p<side>-<step>\` / \`.--padding-<side>-<step>\` on the spacing scale (sides \`t\`/\`b\`/\`s\`/\`e\`/\`x\`/\`y\` or none, spelled short or fully long — for example \`--mb-sm\` and \`--margin-bottom-small\` are the same rule; margin also takes \`auto\`). Usable bare or chained onto any component (for example \`class="instui-view --mb-sm"\`).
 * @modifier --p-md — Applies medium padding on all sides.
 * @modifier --m* — Margin utilities across short, legacy-long, and fully long spellings.
 * @modifier --p* — Padding utilities across short, legacy-long, and fully long spellings.
 * @demo self:spacing
 * @a11y Spacing is visual only: use it to keep text and controls from crowding, not to convey structure — use headings, lists, and landmarks for that. Leave enough space around interactive targets for WCAG 2.5.8, and don't rely on fixed spacing that breaks when users increase text spacing.
 * @example -automatica11y
 * \`\`\`html
 * <div class="--p-md --mt-lg">
 *   <h2>Office hours</h2>
 *   <p>Mondays and Wednesdays, 2–4 pm.</p>
 * </div>
 * \`\`\`
 * @example
 * <div class="--p-md --mt-lg">Padded box with a large top margin.</div>
 */
${rules.join("\n")}`;
  },
});

/** The spacing utilities as a standalone, header-wrapped stylesheet. */
export const spacingUtilitiesCss: Definition["css"] = spacing.css;

/**
 * The layout utilities — `display` and `text-align` as composable, globally-available classes (bare,
 * or chained onto any component).
 *
 * @module
 */
import { css } from "../../lib/css.ts";
import { defineUtility, type Definition } from "../../lib/define.ts";
import { globalModifierSelector } from "@pantoken/utils";

/** The layout utility — composable, global `display` and `text-align` classes. */
export const layout: Definition = defineUtility({
  name: "layout",
  css: (p) => // prettier-ignore
  css`/**
 * @utility layout
 * @selector .--display-flex
 * @global
 * @summary Display and text-align utilities — \`.--display-<value>\` and \`.--text-align-<value>\` — as composable, global classes, usable bare or chained onto any component.
 * @modifier --display-flex — Sets \`display: flex\`.
 * @modifier --display-* — Display utilities: \`block\`, \`inline-block\`, \`inline\`, \`flex\`, \`inline-flex\`, and \`none\`.
 * @modifier --text-align-* — Text-alignment utilities: \`start\`, \`center\`, \`end\`, and \`justify\`.
 * @a11y \`--display-none\` removes an element from the accessibility tree as well as the screen, so use it only for content nobody needs. Flex and grid layout can't reorder content for assistive tech; keep the DOM order meaningful, and don't center or justify long passages of text.
 * @example -automatica11y
 * \`\`\`html
 * <div class="--display-flex --text-align-center">
 *   <span>Course</span>
 *   <span>Grades</span>
 * </div>
 * \`\`\`
 * @example
 * <div class="--display-flex --text-align-center">
 *   <span>One</span>
 *   <span>Two</span>
 * </div>
 */
${[
      ...["block", "inline-block", "inline", "flex", "inline-flex", "none"].map((v) => {
        const name = `display-${v}`;
        return `${globalModifierSelector(p, name)} { display: ${v}; }`;
      }),
      ...(
        [
          ["start", "start"],
          ["center", "center"],
          ["end", "end"],
          ["justify", "justify"],
        ] as const
      ).map(([label, value]) => {
        const name = `text-align-${label}`;
        return `${globalModifierSelector(p, name)} { text-align: ${value}; }`;
      }),
    ].join("\n")}`,
});

/** The layout utilities as a standalone, header-wrapped stylesheet. */
export const layoutUtilitiesCss: Definition["css"] = layout.css;

